function validate([possible]) {
  if (!Array.isArray(possible)) return 'possible must be an array.';
  if (possible.length < 2 || possible.length > 100000) return 'possible needs 2 to 100000 values.';
  if (possible.some(v => v !== 0 && v !== 1)) return 'Each value of possible is 0 or 1.';
  return null;
}

reference:
function minimumLevels(possible) {
  const n = possible.length;
  let total = 0;
  for (const level of possible) {
    total += level === 1 ? 1 : -1;
  }

  let alice = 0;
  for (let i = 0; i < n - 1; i++) {
    alice += possible[i] === 1 ? 1 : -1;
    const bob = total - alice;
    if (alice > bob) {
      return i + 1;
    }
  }
  return -1;
}

