function minimumLevels(possible) {
  const score = part => part.reduce((sum, v) => sum + (v ? 1 : -1), 0);
  for (let k = 1; k < possible.length; k++) {
    if (score(possible.slice(0, k)) > score(possible.slice(k))) return k;
  }
  return -1;
}

