function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 2 + Math.floor(rand() * 9);
  const chance = rand();
  return [Array.from({ length: n }, () => (rand() < chance ? 1 : 0))];
}
